#!/usr/bin/env python3
"""
todo.py -- a tiny command-line to-do list manager.

See SPEC.md at the repository root for the full specification.
"""
import json
import os
import sys

TODOS_FILE = "todos.json"


def load_todos():
    """Load todos.json from the cwd. Missing file -> empty state."""
    if not os.path.exists(TODOS_FILE):
        return {"next_id": 1, "todos": []}
    with open(TODOS_FILE, "r") as f:
        return json.load(f)


def save_todos(data):
    with open(TODOS_FILE, "w") as f:
        json.dump(data, f)


def cmd_add(args):
    if not args:
        sys.stderr.write(
            "Error: add requires <text> argument. Usage: todo add <text>\n"
        )
        return 2

    text = " ".join(args)
    data = load_todos()
    new_id = data["next_id"]
    data["todos"].append({"id": new_id, "text": text, "done": False})
    data["next_id"] = new_id + 1
    save_todos(data)

    sys.stdout.write("Added todo {}: {}\n".format(new_id, text))
    return 0


def cmd_list(args):
    data = load_todos()
    todos = data.get("todos", [])

    if not todos:
        sys.stdout.write("No todos.\n")
        return 0

    lines = []
    for todo in todos:
        marker = "x" if todo["done"] else " "
        lines.append("[{}] {}: {}".format(marker, todo["id"], todo["text"]))
    sys.stdout.write("\n".join(lines) + "\n")
    return 0


def cmd_done(args):
    if not args:
        sys.stderr.write(
            "Error: done requires <id> argument. Usage: todo done <id>\n"
        )
        return 2

    raw_id = args[0]
    try:
        todo_id = int(raw_id, 10)
    except ValueError:
        sys.stderr.write(
            "Error: invalid id '{}': must be an integer.\n".format(raw_id)
        )
        return 2

    data = load_todos()
    for todo in data.get("todos", []):
        if todo["id"] == todo_id:
            todo["done"] = True
            save_todos(data)
            sys.stdout.write("Marked todo {} as done.\n".format(todo_id))
            return 0

    sys.stderr.write("Error: todo {} not found.\n".format(todo_id))
    return 1


def main(argv):
    if not argv:
        sys.stderr.write(
            "Error: no command provided. Usage: todo <add|list|done> [args]\n"
        )
        return 2

    command, rest = argv[0], argv[1:]

    if command == "add":
        return cmd_add(rest)
    elif command == "list":
        return cmd_list(rest)
    elif command == "done":
        return cmd_done(rest)
    else:
        sys.stderr.write(
            "Error: unknown command '{}'. Usage: todo <add|list|done> [args]\n".format(
                command
            )
        )
        return 2


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

